#!/usr/bin/env python3
"""Trace actual V1/V2 geometry and normal-map defects, without editing inputs."""
import argparse,json,hashlib
from pathlib import Path
import numpy as np
import texture2ddecoder
p=argparse.ArgumentParser();p.add_argument('mod_work',type=Path);p.add_argument('new_report',type=Path);a=p.parse_args();assert not a.new_report.exists();rig=a.mod_work/'rig-stage';src=np.load(rig/'landmarks/source.npz');old=np.load(rig/'fit-stowed-v9/fitted.npz');new=np.load(rig/'fit-stowed-v2-proportions/fitted.npz');source=src['positions']*[-1,-1,1];components=old['component'];assert np.array_equal(components,new['component'])
records=[]
for i,label in [(14,'connected torso/head shell'),(13,'upper arm'),(10,'forearm'),(23,'thigh'),(21,'shin'),(20,'main boot')]:
 ix=components==i;records.append({'component':i,'region':label,'source_bbox_m':np.ptp(source[ix],axis=0).tolist(),'V1_bbox_m':np.ptp(old['positions'][ix],axis=0).tolist(),'V2_bbox_m':np.ptp(new['positions'][ix],axis=0).tolist()})
traces=[]
for name,authoring,export,compiled in [('V1','skinned-stowed-v9','skinned-export-v9',a.mod_work/'buzz-test-stage/native-buffers'),('V2','skinned-stowed-v2-proportions','skinned-export-v2-proportions',a.mod_work/'buzz-v2-stage/native-buffers')]:
 au=np.load(rig/authoring/'expected.npz');e=np.load(rig/export/'Buzz-geometry-SKINNED.npz');diff=float(np.max(abs(e['positions']-au['positions'][e['source_vertices']]*[100,-100,100])));assert diff<2e-5
 # Direct engine-style SNORM decode independent of CUE's XOR/127.5 path.
 b=(compiled/'static-vertices.bin').read_bytes();n=len(np.load(compiled/'expected.npz')['normals']);packed=np.frombuffer(b[26:26+n*8],dtype='i1').reshape(n,8);decoded=np.maximum(packed[:,4:7].astype(float)/127,-1);expect=np.load(compiled/'expected.npz')['normals'];error=float(np.max(abs(decoded-expect)));assert error<.012
 traces.append({'stage':name,'authoring_to_export_max_error_cm':diff,'engine_SNORM_normal_max_error':error,'geometry_stretched_by_export':False})
v1compiled=np.load(a.mod_work/'buzz-test-stage/native-buffers/expected.npz');cue=a.mod_work/'buzz-delivery-stage/final-mesh-readback-0';cooked=np.fromfile(cue/'positions.f32',dtype='<f4').reshape(-1,3);assert np.array_equal(cooked,v1compiled['positions'].astype('f4'))
block=(a.mod_work/'buzz-delivery-stage/final-mips-T_Buz_Apparel_01_N/mip-00.bin').read_bytes()[:16];pixels=np.frombuffer(texture2ddecoder.decode_bc5(block,4,4),dtype='u1').reshape(4,4,4)[:,:,[2,1]];assert np.unique(pixels).tolist()==[128,255]
result={'V1_runtime_verified_baseline_sha256':'54b0d16d083dc2f28dee6bc2f7a493a95d082ea4e1d3db2208a2962a95a98670','source_and_fit_comparison':records,'stage_traces':traces,'V1_cooked_positions_exactly_match_compiled_positions':True,'fitting_findings':['V1 torso horizontal scales as low as0.52; transverse limb scales0.72-0.75','V1 shin elongated to reach a native low foot pivot while boot height is compressed to about0.485','V1 facial axis scales1.055/0.544/0.642 driven by Max eye alignment, not source-face proportions','V2 uniform0.9 head scale, wider shells and source-height boots; larger rigid spherical elbows/knees avoid blended-shell collapse'],'striping':{'V1_BC5_R_columns':pixels[:,:,0].tolist(),'V1_BC5_G_columns':pixels[:,:,1].tolist(),'cause':'ISPC BC5 RGBA input produced alternating128/255 columns despite intended flat128,128','fix':'Explicit two BC4 constant endpoint blocks; validate decoded RG channels for every mip','old_validation_gap':'Encoded mip hashes proved transport correctness but did not prove normal pixel contents were flat','tangent_encoder_change':'None: direct signed-normal decode error below0.012; no evidence to alter working tangent storage'},'skeleton_and_integration':'No bone transforms/order, game animation/skeleton references, private MI paths, movement mechanics or capsule changes','limits':['Fixed original animation joint spacing limits exact source limb proportions. V2 changes visual shell widths/hinge offsets and boot height without claiming a new retarget system.','Synthetic poses do not predict every actual game deformation.','Geometry and shading corrections are independently attributable; other visual problems may remain until V2 Windows test.']};a.new_report.write_text(json.dumps(result,indent=2)+'\n');print(json.dumps({'stage_traces':traces,'V1_cooked_matches_compiled':True}))
